window.until = async (fn, ms = 10000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (fn()) return true; await new Promise((r) => setTimeout(r, 100)) } return false };
window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.radio = async (group, label) => { const b = [...document.querySelectorAll('[role=radiogroup][aria-label="' + group + '"] [role=radio]')].find((x) => x.textContent.trim() === label); if (!b) return 'NO RADIO ' + group + '/' + label; b.click(); await sleep(300); return 'radio ' + label };
window.pick = async (title, value) => { const s = document.querySelector('select[title="' + title + '"]'); if (!s) return 'NO SELECT ' + title; const set = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set; set.call(s, value); s.dispatchEvent(new Event('change', { bubbles: true })); await sleep(300); return title + '=' + s.value };
window.settle = async () => { const t0 = performance.now(); await sleep(50); await until(() => document.querySelector('[data-summary]') || document.querySelector('[role=status]') || /error|failed/i.test(document.querySelector('main')?.innerText ?? '')); return Math.round(performance.now() - t0) };
window.chart = () => { const rows = [...document.querySelectorAll('[aria-label="Chart table"] [data-row]')]; return { title: document.querySelector('main h1')?.innerText, sub: document.querySelector('main h1')?.nextElementSibling?.innerText, summary: document.querySelector('[data-summary]')?.innerText ?? null, status: document.querySelector('[role=status]')?.innerText.replace(/\n+/g, ' | ') ?? null, dots: document.querySelectorAll('[data-dot]').length, fills: [...new Set([...document.querySelectorAll('[data-dot] circle:last-child')].map((c) => c.getAttribute('fill')))].slice(0, 6), radii: [...new Set([...document.querySelectorAll('[data-dot] circle:last-child')].map((c) => c.getAttribute('r')))].length, key: document.querySelector('[data-key]')?.innerText.replace(/\n/g, ' ') ?? null, rows: rows.slice(0, 6).map((r) => r.innerText.replace(/\s*\n\s*/g, ' | ')), notes: [...document.querySelectorAll('main .text-warn')].map((e) => e.innerText) } };
window.timed = async (q) => { const t0 = performance.now(); const r = await window.api.stats.query(q); return { engineMs: r.ms, wallMs: Math.round(performance.now() - t0), rows: r.rows.length, total: r.total } };
